{
    "SDK_name": "Android Visual Studio App Center",
    "API_name": "setNetworkRequestsAllowed",
    "effects": ["Control over the network requests made by the AppCenter SDK. If set to false, the SDK continues to collect data but doesn't send it until network requests are allowed."],
    "preconditions": ["AppCenter has been started."],
    "postconditions": ["On setting true, allows the AppCenter SDK to send the collected data over the network; On setting false, it stops the SDK from making any network requests, thereby halting the data sending process, but data will still be collected."],
    "parameters": [
      {
        "index": 0, 
        "rules": [
          {
            "value": "True", 
            "effects": ["Enables the AppCenter SDK to make network requests and send collected data."], 
            "postconditions": ["The AppCenter SDK is permitted to send data over network requests."]

          },
          {
            "value": "False", 
            "effects": ["Disables the AppCenter SDK from making any network requests. Data will be collected but not sent."], 
            "postconditions": ["The AppCenter SDK stops sending data over network requests."]
          }]
      }
    ]
  }
